settings.liquid:
{% comment %}
  Seatopia Oracle Recipe Assistant Widget

  INSTALLATION:
  1. In Shopify Admin, go to Online Store > Themes > Edit Code
  2. Create a new section or paste this into a page template
  3. The API_URL is pre-configured for getdeep.blue

  This widget provides an AI-powered recipe assistant that helps customers
  discover and prepare Seatopia seafood recipes.
{% endcomment %}

<style>
  .oracle-widget-container {
    font-family: 'EB Garamond', Georgia, serif;
    max-width: 720px;
    margin: 40px auto;
    border-radius: 12px;
    overflow: hidden;
    box-shadow: 0 4px 24px rgba(0, 0, 0, 0.08);
    border: 1px solid #e5e5e5;
    background: #fff;
  }

  .oracle-header {
    padding: 20px 24px;
    background: #2c3e50;
    display: flex;
    align-items: center;
    gap: 14px;
  }

  .oracle-avatar {
    width: 44px;
    height: 44px;
    border-radius: 10px;
    background: #3d5a73;
    display: flex;
    align-items: center;
    justify-content: center;
    animation: oracle-glow 3s ease-in-out infinite;
  }

  .oracle-avatar svg {
    width: 22px;
    height: 22px;
    color: white;
  }

  .oracle-title {
    margin: 0;
    font-size: 20px;
    font-weight: 500;
    color: white;
    letter-spacing: 0.5px;
  }

  .oracle-subtitle {
    margin: 0;
    font-size: 13px;
    color: rgba(255,255,255,0.7);
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  }

  .oracle-messages {
    height: 420px;
    overflow-y: auto;
    padding: 24px;
    background: linear-gradient(135deg, #fafafa 0%, #f0f7f9 50%, #fafafa 100%);
    background-size: 200% 200%;
    animation: oracle-shimmer 8s ease-in-out infinite;
    position: relative;
  }

  .oracle-welcome {
    text-align: center;
    padding: 60px 40px;
    color: #666;
    animation: oracle-float 6s ease-in-out infinite;
    position: relative;
  }

  /* Floating bubbles decoration */
  .oracle-bubbles {
    position: absolute;
    width: 100%;
    height: 100%;
    top: 0;
    left: 0;
    pointer-events: none;
    overflow: hidden;
  }

  .oracle-bubble-dot {
    position: absolute;
    background: rgba(44, 62, 80, 0.06);
    border-radius: 50%;
  }

  .oracle-bubble-dot:nth-child(1) {
    width: 20px;
    height: 20px;
    left: 10%;
    bottom: 20%;
    animation: oracle-bubble-rise 7s ease-in-out infinite;
  }

  .oracle-bubble-dot:nth-child(2) {
    width: 12px;
    height: 12px;
    left: 25%;
    bottom: 40%;
    animation: oracle-bubble-rise 5s ease-in-out infinite 1s;
  }

  .oracle-bubble-dot:nth-child(3) {
    width: 16px;
    height: 16px;
    right: 20%;
    bottom: 30%;
    animation: oracle-bubble-rise 6s ease-in-out infinite 2s;
  }

  .oracle-bubble-dot:nth-child(4) {
    width: 10px;
    height: 10px;
    right: 35%;
    bottom: 50%;
    animation: oracle-bubble-rise 8s ease-in-out infinite 0.5s;
  }

  @keyframes oracle-bubble-rise {
    0%, 100% { 
      transform: translateY(0) scale(1);
      opacity: 0.6;
    }
    50% { 
      transform: translateY(-30px) scale(1.1);
      opacity: 0.3;
    }
  }

  .oracle-welcome-icon {
    width: 56px;
    height: 56px;
    margin-bottom: 20px;
    color: #2c3e50;
    animation: oracle-swim 4s ease-in-out infinite;
  }

  .oracle-welcome-title {
    margin: 0 0 12px;
    font-weight: 500;
    color: #2c3e50;
    font-size: 22px;
    font-family: 'EB Garamond', Georgia, serif;
  }

  .oracle-welcome-text {
    margin: 0;
    font-size: 15px;
    line-height: 1.6;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    max-width: 400px;
    margin: 0 auto;
  }

  .oracle-message {
    margin-bottom: 16px;
    display: flex;
  }

  .oracle-message.user {
    justify-content: flex-end;
  }

  .oracle-message.assistant {
    justify-content: flex-start;
  }

  .oracle-bubble {
    max-width: 85%;
    padding: 14px 18px;
    font-size: 15px;
    line-height: 1.7;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  }

  .oracle-message.user .oracle-bubble {
    border-radius: 18px 18px 4px 18px;
    background: #2c3e50;
    color: white;
  }

  .oracle-message.assistant .oracle-bubble {
    border-radius: 18px 18px 18px 4px;
    background: #fff;
    color: #333;
    border: 1px solid #e5e5e5;
  }

  .oracle-bubble a {
    color: #2c3e50;
    text-decoration: underline;
    font-weight: 500;
  }

  .oracle-bubble a .oracle-link-url {
    font-size: 11px;
    opacity: 0.6;
    margin-left: 4px;
    font-weight: 400;
  }

  .oracle-bubble p {
    margin: 0 0 8px;
  }

  .oracle-bubble p:last-child {
    margin-bottom: 0;
  }

  .oracle-bubble ul, .oracle-bubble ol {
    margin: 8px 0;
    padding-left: 20px;
  }

  .oracle-bubble li {
    margin-bottom: 4px;
  }

  .oracle-loading {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 14px 18px;
    border-radius: 18px 18px 18px 4px;
    background: #fff;
    color: #666;
    border: 1px solid #e5e5e5;
  }

  .oracle-spinner {
    width: 16px;
    height: 16px;
    border: 2px solid #e5e5e5;
    border-top-color: #2c3e50;
    border-radius: 50%;
    animation: oracle-spin 1s linear infinite;
  }

  @keyframes oracle-spin {
    to { transform: rotate(360deg); }
  }

  /* Gentle breathing/pulsing animation for the welcome icon */
  @keyframes oracle-breathe {
    0%, 100% { transform: scale(1); opacity: 1; }
    50% { transform: scale(1.05); opacity: 0.8; }
  }

  /* Subtle swimming motion */
  @keyframes oracle-swim {
    0%, 100% { transform: translateX(0) rotate(0deg); }
    25% { transform: translateX(3px) rotate(2deg); }
    75% { transform: translateX(-3px) rotate(-2deg); }
  }

  /* Floating bubbles effect */
  @keyframes oracle-float {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-8px); }
  }

  /* Soft glow pulse for header avatar */
  @keyframes oracle-glow {
    0%, 100% { box-shadow: 0 0 0 0 rgba(61, 90, 115, 0.4); }
    50% { box-shadow: 0 0 12px 4px rgba(61, 90, 115, 0.2); }
  }

  /* Wave shimmer for the messages background */
  @keyframes oracle-shimmer {
    0% { background-position: -200% 0; }
    100% { background-position: 200% 0; }
  }

  .oracle-input-area {
    padding: 16px 24px 20px;
    border-top: 1px solid #e5e5e5;
    background: white;
  }

  .oracle-input-row {
    display: flex;
    gap: 12px;
    align-items: flex-end;
  }

  .oracle-textarea {
    flex: 1;
    padding: 12px 16px;
    border-radius: 8px;
    border: 1px solid #ddd;
    background: #fafafa;
    font-size: 15px;
    line-height: 1.5;
    resize: none;
    outline: none;
    min-height: 46px;
    max-height: 120px;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  }

  .oracle-textarea:focus {
    border-color: #2c3e50;
    background: #fff;
  }

  .oracle-send-btn {
    width: 46px;
    height: 46px;
    border-radius: 8px;
    border: none;
    background: #ddd;
    cursor: not-allowed;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s ease;
  }

  .oracle-send-btn.active {
    background: #2c3e50;
    cursor: pointer;
  }

  .oracle-send-btn:hover.active {
    background: #1a252f;
  }

  .oracle-send-btn svg {
    width: 20px;
    height: 20px;
    color: white;
  }

  .oracle-footer {
    margin: 10px 0 0;
    font-size: 11px;
    color: #999;
    text-align: center;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  }

  /* Mobile responsiveness */
  @media (max-width: 768px) {
    .oracle-widget-container {
      max-width: 100%;
      margin: 20px 16px;
      border-radius: 10px;
    }

    .oracle-header {
      padding: 16px 18px;
    }

    .oracle-avatar {
      width: 38px;
      height: 38px;
    }

    .oracle-title {
      font-size: 18px;
    }

    .oracle-messages {
      height: 350px;
      padding: 16px;
    }

    .oracle-welcome {
      padding: 40px 20px;
    }

    .oracle-welcome-title {
      font-size: 20px;
    }

    .oracle-bubble {
      max-width: 90%;
      padding: 12px 14px;
      font-size: 14px;
    }

    .oracle-input-area {
      padding: 12px 16px 16px;
    }

    .oracle-textarea {
      padding: 10px 14px;
      min-height: 42px;
      font-size: 14px;
    }

    .oracle-send-btn {
      width: 42px;
      height: 42px;
    }
  }

  @media (max-width: 480px) {
    .oracle-widget-container {
      margin: 12px 10px;
      border-radius: 8px;
    }

    .oracle-messages {
      height: 300px;
      padding: 12px;
    }

    .oracle-bubble {
      max-width: 92%;
    }
  }
</style>

<div class="oracle-widget-container" id="oracle-widget">
  <div class="oracle-header">
    <div class="oracle-avatar">
      <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
        <path d="M6 13.87A4 4 0 0 1 7.41 6a5.11 5.11 0 0 1 1.05-1.54 5 5 0 0 1 7.08 0A5.11 5.11 0 0 1 16.59 6 4 4 0 0 1 18 13.87V21H6z"/>
        <line x1="6" y1="17" x2="18" y2="17"/>
      </svg>
    </div>
    <div>
      <h2 class="oracle-title">Oracle</h2>
      <p class="oracle-subtitle">Seatopia Recipe Assistant</p>
    </div>
  </div>

  <div class="oracle-messages" id="oracle-messages">
    <div class="oracle-welcome">
      <div class="oracle-bubbles">
        <div class="oracle-bubble-dot"></div>
        <div class="oracle-bubble-dot"></div>
        <div class="oracle-bubble-dot"></div>
        <div class="oracle-bubble-dot"></div>
      </div>
      <svg class="oracle-welcome-icon" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
        <path d="M6.5 12c.94-3.46 4.94-6 8.5-6 3.56 0 6.06 2.54 7 6-.94 3.47-3.44 6-7 6-3.56 0-7.56-2.53-8.5-6z"/>
        <circle cx="15" cy="12" r="2"/>
        <path d="M2 12h3"/>
        <path d="M4 9l2 1"/>
        <path d="M4 15l2-1"/>
      </svg>
      <p class="oracle-welcome-title">Welcome to Oracle!</p>
      <p class="oracle-welcome-text">Ask me about Seatopia recipes, cooking tips, or what to make with your seafood box.</p>
    </div>
  </div>

  <div class="oracle-input-area">
    <div class="oracle-input-row">
      <textarea 
        class="oracle-textarea" 
        id="oracle-input" 
        placeholder="Ask about recipes..."
        rows="1"
      ></textarea>
      <button class="oracle-send-btn" id="oracle-send">
        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
          <line x1="22" y1="2" x2="11" y2="13"/>
          <polygon points="22 2 15 22 11 13 2 9 22 2"/>
        </svg>
      </button>
    </div>
    <p class="oracle-footer">Powered by Seatopia</p>
  </div>
</div>

<script>
(function() {
  // DeepBlue API URL
  const API_URL = 'https://getdeep.blue/api/public/oracle-chat';

  const messagesContainer = document.getElementById('oracle-messages');
  const inputField = document.getElementById('oracle-input');
  const sendButton = document.getElementById('oracle-send');

  let conversationHistory = [];
  let isLoading = false;

  // Simple markdown-ish parsing for links
  function parseMarkdown(text) {
    // Convert markdown links [text](url) to HTML
    text = text.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" target="_blank" rel="noopener noreferrer">$1 <span class="oracle-link-url">($2)</span></a>');
    // Convert bold **text** to HTML
    text = text.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
    // Convert newlines to <br> and wrap in paragraphs
    const paragraphs = text.split('\n\n');
    return paragraphs.map(p => '<p>' + p.replace(/\n/g, '<br>') + '</p>').join('');
  }

  function updateSendButton() {
    if (inputField.value.trim() && !isLoading) {
      sendButton.classList.add('active');
    } else {
      sendButton.classList.remove('active');
    }
  }

  function autoResize() {
    inputField.style.height = 'auto';
    inputField.style.height = Math.min(inputField.scrollHeight, 120) + 'px';
  }

  function addMessage(role, content) {
    // Remove welcome message if it exists
    const welcome = messagesContainer.querySelector('.oracle-welcome');
    if (welcome) welcome.remove();

    // Remove loading indicator if it exists
    const loading = messagesContainer.querySelector('.oracle-loading-wrapper');
    if (loading) loading.remove();

    const messageDiv = document.createElement('div');
    messageDiv.className = 'oracle-message ' + role;

    const bubble = document.createElement('div');
    bubble.className = 'oracle-bubble';

    if (role === 'assistant') {
      bubble.innerHTML = parseMarkdown(content);
    } else {
      bubble.textContent = content;
    }

    messageDiv.appendChild(bubble);
    messagesContainer.appendChild(messageDiv);
    messagesContainer.scrollTop = messagesContainer.scrollHeight;
  }

  function showLoading() {
    const wrapper = document.createElement('div');
    wrapper.className = 'oracle-message assistant oracle-loading-wrapper';
    wrapper.innerHTML = '<div class="oracle-loading"><div class="oracle-spinner"></div><span>Thinking...</span></div>';
    messagesContainer.appendChild(wrapper);
    messagesContainer.scrollTop = messagesContainer.scrollHeight;
  }

  async function sendMessage() {
    const message = inputField.value.trim();
    if (!message || isLoading) return;

    isLoading = true;
    updateSendButton();

    // Add user message
    addMessage('user', message);
    conversationHistory.push({ role: 'user', content: message });

    inputField.value = '';
    autoResize();

    showLoading();

    try {
      const response = await fetch(API_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          message: message,
          history: conversationHistory.slice(-6)
        })
      });

      const data = await response.json();
      const assistantMessage = data.response || "I'm sorry, I couldn't generate a response.";

      addMessage('assistant', assistantMessage);
      conversationHistory.push({ role: 'assistant', content: assistantMessage });
    } catch (error) {
      console.error('Oracle chat error:', error);
      addMessage('assistant', "I apologize, but I'm having trouble connecting right now. Please try again in a moment.");
    } finally {
      isLoading = false;
      updateSendButton();
    }
  }

  // Event listeners
  inputField.addEventListener('input', function() {
    updateSendButton();
    autoResize();
  });

  inputField.addEventListener('keydown', function(e) {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  });

  sendButton.addEventListener('click', sendMessage);
})();
</script>
